import * as am5 from '@amcharts/amcharts5';
import { IExportingSettings } from '@amcharts/amcharts5/.internal/plugins/exporting/Exporting';
import { IExportingMenuItem } from '@amcharts/amcharts5/.internal/plugins/exporting/ExportingMenu';
import * as am5xy from '@amcharts/amcharts5/xy';
export interface ICombinedTooltipHtmlConfig {
    /**
     * htmlBodyString function takes five arguments and returns a html string that will be shown inside tooltip.
     * this function will be executed once for each series, generally it will create one row in tooltip for one series.
     *
     * valueAtTheToolTip :  the value of the point being shown in the tooltip,
     * dataFieldNameUsedAsCategory: the field name of the x-axis which is shown in the tooltip,
     * dataFieldNameUsedAsValue : the field name in dataObject is used as the value in the tooltip,
     * nameOfTheSeries : name the series
     * strokeColor :  : the color of the series which is shown in the tooltip,
     * tooltipDataItem : tooltip data item
     *
     * This function should return a string that represents the html of the tooltip body.
     * Example:
     *   htmlBodyString: (valueAtTheToolTip, dataFieldNameUsedAsCategory, dataFieldNameUsedAsValue, nameOfTheSeries, strokeColor,tooltipDataItem) => `<div>
     *       <span style="color:${strokeColor};">${nameOfTheSeries}</span>
     *       <span style="color:${strokeColor};">${valueAtTheToolTip}</span>
     *       <span style="color:${strokeColor};">${dataFieldNameUsedAsCategory}%</span>
     *     </div>`
     */
    htmlBodyString: (valueAtTheToolTip: string, dataFieldNameUsedAsCategory: string, dataFieldNameUsedAsValue: string, nameOfTheSeries: string, strokeColor: string, tooltipDataItem: am5.DataItem<am5xy.IXYSeriesDataItem>) => string;
    /**
     * tooltipTitlePosition is an optional property which can be used to set the position of the category body.
     * It can be 'top' or 'bottom'. If not provided, it will be 'top' by default.
     */
    tooltipTitlePosition?: 'top' | 'bottom';
    /**
     * categoryBodyString is an optional function which can be used to set the content for the category in the tooltip.
     * It takes the category value as an argument and returns a html string.
     *
     * Example:
     *   toolTipTitle: (valueOnCategoryField) => `<div>
     *       <span>${category}</span>
     *     </div>`
     */
    toolTipTitle?: (valueOnCategoryField: string) => string;
    /**
     * containerDivStyle is a string that sets the style of the container div.
     * It should be an html style string.
     *
     * Example:
     *   containerDivStyle: "display: flex; color: red;"
     */
    containerDivStyle?: string;
}
export interface ICustomziedTooltipHtmlConfig {
    /**
     * buildCustomziedHtmlString function takes two arguments and returns a html string that will display tooltip.
     *
     * chart: The chart to attach the tooltip,
     * data: this is data we are providing to chart to render with.
     *
     * This function should return a string that represents the html of the tooltip body.
     * Example:
     *   const buildCustomziedHtmlString = (chart: am5xy.XYChart, data: any) => {
     *     let html = '<span>';
     *     let lineColors: any = [];
     *     const xValues = chart.series.values.map((series) => {
     *      const tooltipDataItem = series.get('tooltipDataItem')!;
     *      const valueX = tooltipDataItem?.get('valueX');
     *      if (!valueX) {
     *        return '';
     *      }
     *     const strokeColor = series.get('stroke')!;
     *     lineColors[index] = strokeColor;
     *      return valueX;
     *     });
     *
     *     if (xValues[0] !== '') {
     *       const _period = xValues[0];
     *       const dataPoint = data.find((item: any) => item.category === _period);
     *       const { category, value1, value2, value3, value4, value5 } = dataPoint;
     *       html += `
     *       <div style="display: flex; justify-content: space-between; font-size: 14px; padding: 8px 0px">
     *         <div style="min-width: 120px; width: 100px">Web Search</div>
     *         <div style="display: flex; justify-content: space-between; width: 100%">
     *           <div style="display: flex;flex-direction: column; flex: 1">
     *             <div style="display: flex; align-items: center; color: rgb(116, 118, 124); gap: 3px">
     *               <div style="height: 10px; width: 10px; background-color: ${lineColors[0]}; border-radius: 4px;"></div>
     *               <div>Search</div>
     *             </div>
     *             <div>${value1}</div>
     *           </div>
     *           <div style="display: flex; flex-direction: column; flex: 1">
     *             <div style="display: flex; align-items: center;color: rgb(116, 118, 124); gap: 3px">
     *               <div style="height: 10px; width: 10px; background-color: ${lineColors[1]}; border-radius: 4px;"></div>
     *               <div style="color: rgb(116, 118, 124)">Non Search</div>
     *             </div>
     *             <div>${value2}</div>
     *           </div>
     *         </div>
     *       </div>
     *       `;
     *     }
     *     html += '</span>';
     *     return html;
     *   };
     */
    buildCustomziedHtmlString: (chart: am5xy.XYChart, data: any) => string;
    /**
     * A direction of the tooltip pointer.
     *
     * https://www.amcharts.com/docs/v5/concepts/common-elements/tooltips/#Orientation
     */
    pointerOrientation?: "left" | "right" | "up" | "down" | "vertical" | "horizontal";
}
export type IExportPluginConfig = Omit<IExportingSettings, 'menu'> & {
    menu: {
        /**
         * Array of menu items to be displayed in the export menu.
         */
        items?: IExportingMenuItem[] | undefined;
        /**
         * Id of the container element where the export menu will be appended.
         * If not provided or element is not found, the export menu will be appended to the root element.
         */
        containerId?: string;
        /**
         * Whether to use the default CSS for the export menu.
         */
        useDefaultCSS?: boolean;
        /**
         * Whether to automatically close the menu after an item is clicked.
         */
        autoClose?: boolean;
        /**
         *  Whether to deactivate the root element.
         */
        deactivateRoot?: boolean;
        /**
         * HTML content to be used as the menu icon.
         */
        menuIconHTMLLiteral?: string;
        /**
         * align menu icon to left or right
         */
        align?: 'left' | 'right';
        /**
         * vertical alignment of the menu icon
         */
        valign?: 'top' | 'bottom';
    };
};
